export function Icon({ name, className }: { name: IconName; className?: string }) {
  const icon = iconDefinitions[name];
  const paint = icon.filled
    ? { fill: 'currentColor', stroke: 'none', fillRule: 'evenodd' as const }
    : { fill: 'none', stroke: 'currentColor', strokeWidth: icon.strokeWidth, strokeLinecap: 'round' as const, strokeLinejoin: 'round' as const };
  return <svg className={className} viewBox={icon.viewBox} width="1em" height="1em" aria-hidden="true" focusable="false" {...paint}>
    {icon.paths.map(d => <path key={d} d={d} />)}
  </svg>;
}

export type { IconName };
